INSERT INTO `oc_product_description` (`product_id`, `language_id`, `name`, `description`, `tag`, `meta_title`, `meta_description`, `meta_keyword`)
VALUES (35, 2, 'Товар 8', '&lt;p&gt;\r\n	Товар 8&lt;/p&gt;\r\n', '', 'Товар 8', '', ''),
       (48, 2, 'iPod Classic',
        '&lt;div class=&quot;cpt_product_description &quot;&gt;\r\n	&lt;div&gt;\r\n		&lt;p&gt;\r\n			&lt;strong&gt;Больше места для музыки.&lt;/strong&gt;&lt;/p&gt;\r\n		&lt;p&gt;\r\n			С памятью 80 ГБ или 160 ГБ и до 40 часов работы от батареи новый iPod classic дает до 40 000 песен или до 200 часов видео — в любом сочетании и где угодно.&lt;/p&gt;\r\n		&lt;p&gt;\r\n			&lt;strong&gt;Cover Flow.&lt;/strong&gt;&lt;/p&gt;\r\n		&lt;p&gt;\r\n			Листайте музыкальную коллекцию по обложкам альбомов. Выберите альбом, чтобы перевернуть его и увидеть список дорожек.&lt;/p&gt;\r\n		&lt;p&gt;\r\n			&lt;strong&gt;Улучшенный интерфейс.&lt;/strong&gt;&lt;/p&gt;\r\n		&lt;p&gt;\r\n			Совершенно новый способ просматривать музыку и видео.&lt;/p&gt;\r\n		&lt;p&gt;\r\n			&lt;strong&gt;Более изящный дизайн.&lt;/strong&gt;&lt;/p&gt;\r\n		&lt;p&gt;\r\n			Красивый, прочный и изящнее прежнего: корпус iPod classic теперь из анодированного алюминия и полированной нержавеющей стали со скругленными краями.&lt;/p&gt;\r\n	&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;!-- cpt_container_end --&gt;',
        '', 'iPod Classic', '', ''),
       (40, 2, 'iPhone', '&lt;p class=&quot;intro&quot;&gt;\r\n	iPhone — революционный мобильный телефон: чтобы позвонить, достаточно коснуться имени или номера в адресной книге, списке избранного или журнале вызовов. Контакты сами синхронизируются с PC, Mac или интернет-службой. Голосовую почту можно выбирать и слушать в любом порядке, как электронную почту.&lt;/p&gt;\r\n', '', 'iPhone', '', ''),
       (28, 2, 'HTC Touch HD',
        '&lt;p&gt;\r\n	HTC Touch — в высоком разрешении. Смотрите музыкальные видео и потоковое видео с поразительной четкостью: такие мобильные возможности раньше казались невозможными. Тонкий HTC Touch HD открывает следующее поколение функций одним касанием. Полная интеграция с Windows Mobile Professional 6.1, сверхбыстрый 3.5G, GPS, камера 5 Мп и многое другое — на поразительно четком сенсорном экране 3,8&amp;quot; WVGA. Управляйте мобильным миром вместе с HTC Touch HD.&lt;/p&gt;\r\n&lt;p&gt;\r\n	&lt;strong&gt;Характеристики&lt;/strong&gt;&lt;/p&gt;\r\n&lt;ul&gt;\r\n	&lt;li&gt;\r\n		Процессор Qualcomm&amp;reg; MSM 7201A&amp;trade; 528 МГц&lt;/li&gt;\r\n	&lt;li&gt;\r\n		Операционная система Windows Mobile&amp;reg; 6.1 Professional&lt;/li&gt;\r\n	&lt;li&gt;\r\n		Память: 512 МБ ПЗУ, 288 МБ ОЗУ&lt;/li&gt;\r\n	&lt;li&gt;\r\n		Размеры: 115 мм x 62,8 мм x 12 мм / 146,4 г&lt;/li&gt;\r\n	&lt;li&gt;\r\n		Плоский сенсорный экран TFT-LCD 3,8 дюйма с разрешением WVGA 480 x 800&lt;/li&gt;\r\n	&lt;li&gt;\r\n		HSDPA/WCDMA: Европа/Азия: 900/2100 МГц; до 2 Мбит/с на передачу и 7,2 Мбит/с на прием&lt;/li&gt;\r\n	&lt;li&gt;\r\n		Четырехдиапазонный GSM/GPRS/EDGE: Европа/Азия: 850/900/1800/1900 МГц (частоты, доступность HSUPA и скорость передачи зависят от оператора.)&lt;/li&gt;\r\n	&lt;li&gt;\r\n		Управление через HTC TouchFLO&amp;trade; 3D &amp;amp; сенсорные кнопки на передней панели&lt;/li&gt;\r\n	&lt;li&gt;\r\n		Поддержка GPS и A-GPS&lt;/li&gt;\r\n	&lt;li&gt;\r\n		Bluetooth&amp;reg; 2.0 с Enhanced Data Rate и A2DP для беспроводных стереогарнитур&lt;/li&gt;\r\n	&lt;li&gt;\r\n		Wi-Fi&amp;reg;: IEEE 802.11 b/g&lt;/li&gt;\r\n	&lt;li&gt;\r\n		HTC ExtUSB&amp;trade; (11-pin mini-USB 2.0)&lt;/li&gt;\r\n	&lt;li&gt;\r\n		Цветная камера 5 мегапикселей с автофокусом&lt;/li&gt;\r\n	&lt;li&gt;\r\n		Цветная CMOS-камера VGA&lt;/li&gt;\r\n	&lt;li&gt;\r\n		Встроенное гнездо 3,5 мм, микрофон, динамик и FM-радио&lt;/li&gt;\r\n	&lt;li&gt;\r\n		Форматы мелодий: AAC, AAC+, eAAC+, AMR-NB, AMR-WB, QCP, MP3, WMA, WAV&lt;/li&gt;\r\n	&lt;li&gt;\r\n		40 полифонических голосов и стандартный MIDI форматов 0 и 1 (SMF)/SP MIDI&lt;/li&gt;\r\n	&lt;li&gt;\r\n		Аккумулятор Lithium-ion или Lithium-ion polymer 1350 мА·ч&lt;/li&gt;\r\n	&lt;li&gt;\r\n		Слот расширения: карта памяти microSD&amp;trade; (совместима с SD 2.0)&lt;/li&gt;\r\n	&lt;li&gt;\r\n		Адаптер питания: 100–240 В переменного тока, 50/60 Гц; выход 5 В и 1 А&lt;/li&gt;\r\n	&lt;li&gt;\r\n		Особые возможности: FM-радио, G-сенсор&lt;/li&gt;\r\n&lt;/ul&gt;\r\n',
        '', '	 HTC Touch HD', '', ''),
       (44, 2, 'MacBook Air', '&lt;div&gt;\r\n	MacBook Air ультратонкий, сверхпортативный и совсем не похож на другие компьютеры. Сантиметры и граммы не исчезают за одну ночь. Это результат пересмотра привычного, нескольких беспроводных новшеств и прорывного дизайна. С MacBook Air у мобильных компьютеров внезапно появился новый стандарт.&lt;/div&gt;\r\n', '', 'MacBook Air', '', ''),
       (45, 2, 'MacBook Pro',
        '&lt;div class=&quot;cpt_product_description &quot;&gt;\r\n	&lt;div&gt;\r\n		&lt;p&gt;\r\n			&lt;b&gt;Новейшая мобильная архитектура Intel&lt;/b&gt;&lt;/p&gt;\r\n		&lt;p&gt;\r\n			На самых современных мобильных процессорах Intel новый MacBook Pro с Core 2 Duo более чем на 50% быстрее первого MacBook Pro с Core Duo и поддерживает до 4 ГБ оперативной памяти.&lt;/p&gt;\r\n		&lt;p&gt;\r\n			&lt;b&gt;Графика переднего края&lt;/b&gt;&lt;/p&gt;\r\n		&lt;p&gt;\r\n			NVIDIA GeForce 8600M GT дает исключительную мощность графики. Для большой рабочей области модель с экраном 17 дюймов можно заказать с разрешением 1920 x 1200.&lt;/p&gt;\r\n		&lt;p&gt;\r\n			&lt;b&gt;Создан для жизни в дороге&lt;/b&gt;&lt;/p&gt;\r\n		&lt;p&gt;\r\n			Магнитный разъем питания и клавиатура с подсветкой и датчиком освещенности ставят MacBook Pro особняком.&lt;/p&gt;\r\n		&lt;p&gt;\r\n			&lt;b&gt;Подключайтесь. Создавайте. Общайтесь.&lt;/b&gt;&lt;/p&gt;\r\n		&lt;p&gt;\r\n			Быстро настройте видеозвонок со встроенной камерой iSight. Управляйте презентациями и медиа с расстояния до 9 метров пультом Apple Remote. Подключайте быстрые устройства через FireWire 800 и DVI.&lt;/p&gt;\r\n		&lt;p&gt;\r\n			&lt;b&gt;Беспроводная связь нового поколения&lt;/b&gt;&lt;/p&gt;\r\n		&lt;p&gt;\r\n			С беспроводной технологией 802.11n MacBook Pro дает до пяти раз большую скорость и до двух раз большую дальность, чем технологии прошлого поколения.&lt;/p&gt;\r\n	&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;!-- cpt_container_end --&gt;',
        '', 'MacBook Pro', '', ''),
       (29, 2, 'Palm Treo Pro',
        '&lt;p&gt;\r\n	По-новому постройте рабочий день со смартфоном Palm Treo Pro. Он одинаково удобен для рабочей и личной почты, встреч и контактов, а в дороге пригодятся Wi-Fi и GPS. Потом можно посмотреть видео на YouTube, новости и спорт в интернете или послушать несколько песен. Совмещайте работу и отдых так, как вам удобно, с Palm Treo Pro.&lt;/p&gt;\r\n&lt;p&gt;\r\n	&lt;strong&gt;Характеристики&lt;/strong&gt;&lt;/p&gt;\r\n&lt;ul&gt;\r\n	&lt;li&gt;\r\n		Windows Mobile&amp;reg; 6.1 Professional Edition&lt;/li&gt;\r\n	&lt;li&gt;\r\n		Процессор Qualcomm&amp;reg; MSM7201 400 МГц&lt;/li&gt;\r\n	&lt;li&gt;\r\n		Трансфлективный цветной сенсорный TFT-экран 320x320&lt;/li&gt;\r\n	&lt;li&gt;\r\n		Радиомодуль HSDPA/UMTS/EDGE/GPRS/GSM&lt;/li&gt;\r\n	&lt;li&gt;\r\n		Трехдиапазонный UMTS &amp;mdash; 850 МГц, 1900 МГц, 2100 МГц&lt;/li&gt;\r\n	&lt;li&gt;\r\n		Четырехдиапазонный GSM &amp;mdash; 850/900/1800/1900&lt;/li&gt;\r\n	&lt;li&gt;\r\n		802.11b/g с аутентификацией WPA, WPA2 и 801.1x&lt;/li&gt;\r\n	&lt;li&gt;\r\n		Встроенный GPS&lt;/li&gt;\r\n	&lt;li&gt;\r\n		Bluetooth версии 2.0 + Enhanced Data Rate&lt;/li&gt;\r\n	&lt;li&gt;\r\n		Накопитель 256 МБ (пользователю доступно 100 МБ), 128 МБ ОЗУ&lt;/li&gt;\r\n	&lt;li&gt;\r\n		Камера 2,0 мегапикселя, цифровой зум до 8x и видеосъемка&lt;/li&gt;\r\n	&lt;li&gt;\r\n		Съемный аккумулятор lithium-ion 1500 мА·ч&lt;/li&gt;\r\n	&lt;li&gt;\r\n		До 5,0 часов разговора и до 250 часов ожидания&lt;/li&gt;\r\n	&lt;li&gt;\r\n		Расширение картой MicroSDHC (до 32 ГБ)&lt;/li&gt;\r\n	&lt;li&gt;\r\n		MicroUSB 2.0 для синхронизации и зарядки&lt;/li&gt;\r\n	&lt;li&gt;\r\n		Гнездо стереогарнитуры 3,5 мм&lt;/li&gt;\r\n	&lt;li&gt;\r\n		60 мм (Ш) x 114 мм (В) x 13,5 мм (Т) / 133 г&lt;/li&gt;\r\n&lt;/ul&gt;\r\n',
        '', 'Palm Treo Pro', '', ''),
       (36, 2, 'iPod Nano',
        '&lt;div&gt;\r\n	&lt;p&gt;\r\n		&lt;strong&gt;Видео в кармане.&lt;/strong&gt;&lt;/p&gt;\r\n	&lt;p&gt;\r\n		Это маленький iPod с одной большой идеей: видео. Самый популярный в мире плеер теперь показывает фильмы, телепередачи и другое на двухдюймовом экране, который на 65% ярче прежнего.&lt;/p&gt;\r\n	&lt;p&gt;\r\n		&lt;strong&gt;Cover Flow.&lt;/strong&gt;&lt;/p&gt;\r\n	&lt;p&gt;\r\n		Листайте музыкальную коллекцию по обложкам альбомов. Выберите альбом, чтобы перевернуть его и увидеть список дорожек.&lt;strong&gt;&amp;nbsp;&lt;/strong&gt;&lt;/p&gt;\r\n	&lt;p&gt;\r\n		&lt;strong&gt;Улучшенный интерфейс.&lt;/strong&gt;&lt;/p&gt;\r\n	&lt;p&gt;\r\n		Совершенно новый способ просматривать музыку и видео.&lt;/p&gt;\r\n	&lt;p&gt;\r\n		&lt;strong&gt;Тонкий и цветной.&lt;/strong&gt;&lt;/p&gt;\r\n	&lt;p&gt;\r\n		Корпус из анодированного алюминия и полированной нержавеющей стали и пять цветов: iPod nano выглядит так, чтобы производить впечатление.&lt;/p&gt;\r\n	&lt;p&gt;\r\n		&lt;strong&gt;iTunes.&lt;/strong&gt;&lt;/p&gt;\r\n	&lt;p&gt;\r\n		Бесплатный iTunes помогает выбирать и покупать миллионы песен, фильмов, телепередач, аудиокниг и игр, а также скачивать бесплатные подкасты в iTunes Store. Можно импортировать свою музыку, вести всю медиатеку и легко синхронизировать iPod или iPhone.&lt;/p&gt;\r\n&lt;/div&gt;\r\n',
        '', 'iPod Nano', '', ''),
       (46, 2, 'Sony VAIO', '&lt;div&gt;\r\n	Небывалая мощность. Пришло следующее поколение вычислительных технологий. В новейших ноутбуках VAIO — самая мощная новинка Intel: технология процессора Intel&amp;reg; Centrino&amp;reg; 2. Высокая скорость, расширенная беспроводная связь, лучшая поддержка мультимедиа и выше энергоэффективность собраны в одном чипе.&lt;/div&gt;\r\n', '', 'Sony VAIO', '', ''),
       (47, 2, 'HP LP3065', '&lt;p&gt;\r\n	Остановите коллег на месте новым монитором HP LP3065 с диагональю 30 дюймов. Этот флагман дает лучшие в классе изображение и возможности презентаций на огромном широком экране и позволяет работать так удобно, что можно забыть, что вы в офисе&lt;/p&gt;\r\n', '', 'HP LP3065', '', ''),
       (32, 2, 'iPod Touch',
        '&lt;p&gt;\r\n	&lt;strong&gt;Революционный мультисенсорный интерфейс.&lt;/strong&gt;&lt;br /&gt;\r\n	В iPod touch тот же мультисенсорный экран, что и в iPhone. Сведите пальцы, чтобы увеличить фото. Пролистывайте песни и видео одним движением. Листайте библиотеку по обложкам с Cover Flow.&lt;/p&gt;\r\n&lt;p&gt;\r\n	&lt;strong&gt;Великолепный широкий экран 3,5 дюйма.&lt;/strong&gt;&lt;br /&gt;\r\n	Фильмы, телепередачи и фото оживают ярким цветом на экране 320 x 480 пикселей.&lt;/p&gt;\r\n&lt;p&gt;\r\n	&lt;strong&gt;Музыка загружается прямо из iTunes.&lt;/strong&gt;&lt;br /&gt;\r\n	Покупайте в iTunes Wi-Fi Music Store откуда угодно, где есть Wi-Fi.1 Найдите музыку просмотром или поиском, послушайте фрагмент и купите одним касанием.&lt;/p&gt;\r\n&lt;p&gt;\r\n	&lt;strong&gt;Выходите в интернет через Wi-Fi.&lt;/strong&gt;&lt;br /&gt;\r\n	Смотрите сайты в Safari и видео YouTube на первом iPod со встроенным Wi-Fi&lt;br /&gt;\r\n	&amp;nbsp;&lt;/p&gt;\r\n',
        '', 'iPod Touch', '', ''),
       (41, 2, 'iMac', '&lt;div&gt;\r\n	Казалось, в iMac уже есть все, но теперь есть еще больше. Более мощные процессоры Intel Core 2 Duo. И больше памяти в базовой конфигурации. Вместе с Mac OS X Leopard и iLife &acute;08 он еще сильнее собирает все в одном корпусе. iMac умещает отличную производительность в поразительно тонком объеме.&lt;/div&gt;\r\n', '', 'iMac', '', ''),
       (33, 2, 'Samsung SyncMaster 941BW', '&lt;div&gt;\r\n	Представьте большой экран без потери скорости. Монитор 941BW с диагональю 19&amp;quot; сочетает широкий формат и быстрый отклик пикселей: изображение крупнее, места для работы больше, движение четкое. Технологии MagicBright 2, MagicColor и MagicTune помогают получить нужную картинку в любой ситуации, а узкие рамки и регулируемая подставка задают вид, который вам нужен. С широким аналого-цифровым ЖК-монитором Samsung 941BW это легко представить.&lt;/div&gt;\r\n', '', 'Samsung SyncMaster 941BW', '', ''),
       (34, 2, 'iPod Shuffle', '&lt;div&gt;\r\n	&lt;strong&gt;Создан, чтобы его носили.&lt;/strong&gt;\r\n	&lt;p&gt;\r\n		Зацепите самый носимый в мире плеер и берите с собой до 240 песен. Пять цветов, из них четыре новых, чтобы музыка стала частью вашего стиля.&lt;/p&gt;\r\n	&lt;p&gt;\r\n		&lt;strong&gt;Случайность встречается с ритмом.&lt;/strong&gt;&lt;/p&gt;\r\n	&lt;p&gt;\r\n		С автозаполнением iTunes плеер iPod shuffle дает новое звучание при каждой синхронизации. Чтобы было еще разнообразнее, перемешивайте песни во время воспроизведения переключателем.&lt;/p&gt;\r\n	&lt;strong&gt;Все просто.&lt;/strong&gt;\r\n	&lt;p&gt;\r\n		Заряжайте и синхронизируйте через USB-док из комплекта. Кнопки iPod shuffle управляются одной рукой. До 12 часов музыки подряд без пропусков.&lt;/p&gt;\r\n&lt;/div&gt;\r\n', '', 'iPod Shuffle', '', ''),
       (43, 2, 'MacBook',
        '&lt;div&gt;\r\n	&lt;p&gt;\r\n		&lt;b&gt;Процессор Intel Core 2 Duo&lt;/b&gt;&lt;/p&gt;\r\n	&lt;p&gt;\r\n		С процессором Intel Core 2 Duo частотой до 2,16 ГГц новый MacBook — самый быстрый за все время.&lt;/p&gt;\r\n	&lt;p&gt;\r\n		&lt;b&gt;1 ГБ памяти, более емкие диски&lt;/b&gt;&lt;/p&gt;\r\n	&lt;p&gt;\r\n		Теперь у нового MacBook 1 ГБ памяти в базе и более емкие диски во всей линейке: удобно запускать больше любимых программ и хранить растущие коллекции.&lt;/p&gt;\r\n	&lt;p&gt;\r\n		&lt;b&gt;Тонкий корпус толщиной 1,08 дюйма&lt;/b&gt;&lt;/p&gt;\r\n	&lt;p&gt;\r\n		MacBook легко брать с собой: прочный поликарбонатный корпус, встроенные беспроводные технологии и адаптер MagSafe, который сам отсоединяется, если кто-то заденет кабель.&lt;/p&gt;\r\n	&lt;p&gt;\r\n		&lt;b&gt;Встроенная камера iSight&lt;/b&gt;&lt;/p&gt;\r\n	&lt;p&gt;\r\n		Сразу из коробки можно созвониться по видео с друзьями или семьей,2 записать видео за столом или сделать забавные снимки в Photo Booth&lt;/p&gt;\r\n&lt;/div&gt;\r\n',
        '', 'MacBook', '', ''),
       (31, 2, 'Nikon D300',
        '&lt;div class=&quot;cpt_product_description &quot;&gt;\r\n	&lt;div&gt;\r\n		Камера D300 с 12,3 эффективными мегапикселями собрана для профессиональной работы: новые технологии и возможности, унаследованные от недавно анонсированной профессиональной цифровой зеркальной камеры Nikon D3, дают серьезным фотографам высокую скорость и подвижность.&lt;br /&gt;\r\n		&lt;br /&gt;\r\n		Как и D3, D300 использует фирменную систему обработки изображения Nikon EXPEED: она дает скорость и мощность для многих новых функций. У D300 новая 51-точечная автофокусировка с 3D-слежением Nikon и два новых режима LiveView, в которых кадр строится по ЖК-экрану высокого разрешения. Система распознавания сюжета похожа на ту, что в D3: она заметно повышает точность автофокуса, автоэкспозиции и автоматического баланса белого, распознавая объект или сюжет и учитывая это в расчетах трех функций.&lt;br /&gt;\r\n		&lt;br /&gt;\r\n		D300 включается за 0,13 секунды и снимает с почти незаметной задержкой спуска 45 миллисекунд. Скорость серийной съемки — шесть кадров в секунду, а с дополнительным батарейным блоком MB-D10 — до восьми. Непрерывная серия — до 100 кадров при полном разрешении 12,3 мегапикселя. (настройка NORMAL-LARGE, карта CompactFlash SanDisk Extreme IV 1 ГБ.)&lt;br /&gt;\r\n		&lt;br /&gt;\r\n		В D300 набор новых технологий, которые заметно повышают точность, контроль и отдачу техники. Новая система распознавания сюжета развивает известный 1005-сегментный датчик Nikon: он узнает цвета и световые узоры и до снимка понимает, что и какой сюжет снимается. Эти данные уточняют автофокус, автоэкспозицию и баланс белого. Камера лучше ведет движущиеся объекты и, опознав их, быстрее и точнее выбирает точки фокуса. Она также разбирает света, точнее считает экспозицию и определяет источники света для более верного баланса белого.&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;!-- cpt_container_end --&gt;',
        '', 'Nikon D300', '', ''),
       (49, 2, 'Samsung Galaxy Tab 10.1',
        '&lt;p&gt;\r\n	Samsung Galaxy Tab 10.1 — самый тонкий в мире планшет толщиной 8,6 мм. Он работает на Android 3.0 Honeycomb и двухъядерном процессоре Tegra 2 с частотой 1 ГГц, как и младшая модель Samsung Galaxy Tab 8.9.&lt;/p&gt;\r\n&lt;p&gt;\r\n	Samsung Galaxy Tab 10.1 дает чистый Android 3.0 и добавляет TouchWiz UX, или TouchWiz 4.0, &amp;ndash; живую панель, которую можно заполнить фотографиями, закладками и социальными лентами. Емкостный сенсорный экран WXGA 10,1 дюйма с разрешением 1280 x 800, задняя камера 3 мегапикселя со вспышкой LED и передняя камера 2 мегапикселя, HSPA+ до 21 Мбит/с, запись HD 720p, воспроизведение HD 1080p, DLNA, Bluetooth 2.1, USB 2.0, гироскоп, Wi-Fi 802.11 a/b/g/n, слот micro-SD, гнездо 3,5 мм и слот SIM. В комплекте Samsung Stick &amp;ndash; микрофон Bluetooth, который носят в кармане как ручку, и док-станция с активным сабвуфером.&lt;/p&gt;\r\n&lt;p&gt;\r\n	Samsung Galaxy Tab 10.1 выйдет в версиях 16 ГБ / 32 ГБ / 64 ГБ с предустановленными Social Hub, Reader&amp;rsquo;s Hub, Music Hub и Samsung Mini Apps Tray &amp;ndash; лотком частых приложений, который упрощает работу с несколькими задачами. Поддерживается Adobe Flash Player 10.2, аккумулятор 6860 мА·ч дает до 10 часов воспроизведения видео.&amp;nbsp;&amp;auml;&amp;ouml;&lt;/p&gt;\r\n',
        '', 'Samsung Galaxy Tab 10.1', '', ''),
       (42, 2, 'Apple Cinema 30&quot;',
        '&lt;p&gt;\r\n	&lt;font face=&quot;helvetica,geneva,arial&quot; size=&quot;2&quot;&gt;&lt;font face=&quot;Helvetica&quot; size=&quot;2&quot;&gt;Дисплей Apple Cinema HD с диагональю 30 дюймов дает разрешение 2560 x 1600 пикселей. Он сделан для тех, кто работает с изображением: больше места для инструментов и палитр, которыми правят, верстают и собирают работу. Вместе с Mac Pro, MacBook Pro или PowerMac G5 предел того, что можно сделать, исчезает. &lt;br&gt;\r\n	&lt;br&gt;\r\n	&lt;/font&gt;&lt;font face=&quot;Helvetica&quot; size=&quot;2&quot;&gt;В Cinema HD жидкокристаллическая матрица активного типа: изображение без мерцания, вдвое ярче, вдвое четче и с вдвое большим контрастом, чем у обычного кинескопа. В отличие от других плоских панелей здесь чистый цифровой интерфейс: картинка без искажений и без постоянной подстройки. Больше 4 миллионов цифровых пикселей — экран особенно уместен в науке и технике, например для молекулярных структур или геологических данных. &lt;br&gt;\r\n	&lt;br&gt;\r\n	&lt;/font&gt;&lt;font face=&quot;Helvetica&quot; size=&quot;2&quot;&gt;Cinema HD точно и ярко передает цвет: до 16,7 миллиона цветов в широком охвате, от мягкой пастели до насыщенных тонов. Широкий угол обзора держит цвет ровным от края до края. Технология Apple ColorSync позволяет строить свои профили и сохранять цвет одинаковым на экране и в печати. Таким экраном можно спокойно пользоваться там, где цвет критичен. &lt;br&gt;\r\n	&lt;br&gt;\r\n	&lt;/font&gt;&lt;font face=&quot;Helvetica&quot; size=&quot;2&quot;&gt;Новый алюминиевый корпус и очень тонкая рамка делают картинку точнее. У каждого экрана два порта FireWire 400 и два порта USB 2.0, поэтому iSight, iPod, цифровые и обычные камеры, диски, принтеры и сканеры подключать проще. За счет тонкого и легкого ЖК-корпуса новые дисплеи поддерживают стандарт крепления VESA (Video Electronics Standards Association). С дополнительным комплектом Cinema Display VESA Mount Adapter экран можно повесить там, где удобнее работать. &lt;br&gt;\r\n	&lt;br&gt;\r\n	&lt;/font&gt;&lt;font face=&quot;Helvetica&quot; size=&quot;2&quot;&gt;У Cinema HD один кабель с аккуратным разветвлением на USB 2.0, FireWire 400 и чистое цифровое соединение по отраслевому интерфейсу Digital Video Interface (DVI). Подключение DVI дает прямой цифровой сигнал.&lt;br&gt;\r\n	&lt;/font&gt;&lt;/font&gt;&lt;/p&gt;\r\n&lt;h3&gt;\r\n	Характеристики:&lt;/h3&gt;\r\n&lt;p&gt;\r\n	Непревзойденное качество изображения&lt;/p&gt;\r\n&lt;ul&gt;\r\n	&lt;li&gt;\r\n		Жидкокристаллический экран активного типа с видимой диагональю 30 дюймов: поразительная четкость и живой насыщенный цвет.&lt;/li&gt;\r\n	&lt;li&gt;\r\n		Разрешение 2560 x 1600 пикселей для фото и видео высокой четкости.&lt;/li&gt;\r\n	&lt;li&gt;\r\n		Широкий формат: две полные страницы текста и графики одновременно.&lt;/li&gt;\r\n	&lt;li&gt;\r\n		Стандартный разъем DVI для прямого подключения к настольным компьютерам и ноутбукам Mac и Windows&lt;/li&gt;\r\n	&lt;li&gt;\r\n		Очень широкий угол обзора (170 градусов) по горизонтали и вертикали.&lt;/li&gt;\r\n	&lt;li&gt;\r\n		Очень быстрый отклик пикселей для плавного цифрового видео.&lt;/li&gt;\r\n	&lt;li&gt;\r\n		16,7 миллиона насыщенных цветов для любых графических задач.&lt;/li&gt;\r\n&lt;/ul&gt;\r\n&lt;p&gt;\r\n	Простые установка и работа&lt;/p&gt;\r\n&lt;ul&gt;\r\n	&lt;li&gt;\r\n		Один кабель с аккуратным разветвлением к портам DVI, USB и FireWire&lt;/li&gt;\r\n	&lt;li&gt;\r\n		Встроенный двухпортовый концентратор USB 2.0 для настольных устройств.&lt;/li&gt;\r\n	&lt;li&gt;\r\n		Два порта FireWire 400 для iSight и других настольных устройств&lt;/li&gt;\r\n&lt;/ul&gt;\r\n&lt;p&gt;\r\n	Строгий и изящный вид&lt;/p&gt;\r\n&lt;ul&gt;\r\n	&lt;li&gt;\r\n		Огромное рабочее поле при очень малой площади на столе.&lt;/li&gt;\r\n	&lt;li&gt;\r\n		Узкая рамка, чтобы два экрана рядом меньше мешали глазу&lt;/li&gt;\r\n	&lt;li&gt;\r\n		Особый шарнир, который настраивается без усилия&lt;/li&gt;\r\n	&lt;li&gt;\r\n		Крепления VESA (адаптер Apple Cinema Display VESA Mount Adapter продается отдельно)&lt;/li&gt;\r\n&lt;/ul&gt;\r\n&lt;h3&gt;\r\n	Технические характеристики&lt;/h3&gt;\r\n&lt;p&gt;\r\n	&lt;b&gt;Размер экрана (видимая диагональ)&lt;/b&gt;&lt;/p&gt;\r\n&lt;ul&gt;\r\n	&lt;li&gt;\r\n		Apple Cinema HD Display: 30 дюймов (видимо 29,7 дюйма)&lt;/li&gt;\r\n&lt;/ul&gt;\r\n&lt;p&gt;\r\n	&lt;b&gt;Тип экрана&lt;/b&gt;&lt;/p&gt;\r\n&lt;ul&gt;\r\n	&lt;li&gt;\r\n		Жидкокристаллический дисплей активного типа на тонкопленочных транзисторах (TFT, AMLCD)&lt;/li&gt;\r\n&lt;/ul&gt;\r\n&lt;p&gt;\r\n	&lt;b&gt;Разрешения&lt;/b&gt;&lt;/p&gt;\r\n&lt;ul&gt;\r\n	&lt;li&gt;\r\n		2560 x 1600 пикселей (оптимальное разрешение)&lt;/li&gt;\r\n	&lt;li&gt;\r\n		2048 x 1280&lt;/li&gt;\r\n	&lt;li&gt;\r\n		1920 x 1200&lt;/li&gt;\r\n	&lt;li&gt;\r\n		1280 x 800&lt;/li&gt;\r\n	&lt;li&gt;\r\n		1024 x 640&lt;/li&gt;\r\n&lt;/ul&gt;\r\n&lt;p&gt;\r\n	&lt;b&gt;Цвета (максимум)&lt;/b&gt;&lt;/p&gt;\r\n&lt;ul&gt;\r\n	&lt;li&gt;\r\n		16,7 миллиона&lt;/li&gt;\r\n&lt;/ul&gt;\r\n&lt;p&gt;\r\n	&lt;b&gt;Угол обзора (типичный)&lt;/b&gt;&lt;/p&gt;\r\n&lt;ul&gt;\r\n	&lt;li&gt;\r\n		170° horizontal; 170° vertical&lt;/li&gt;\r\n&lt;/ul&gt;\r\n&lt;p&gt;\r\n	&lt;b&gt;Яркость (типичная)&lt;/b&gt;&lt;/p&gt;\r\n&lt;ul&gt;\r\n	&lt;li&gt;\r\n		Cinema HD 30 дюймов: 400 кд/м2&lt;/li&gt;\r\n&lt;/ul&gt;\r\n&lt;p&gt;\r\n	&lt;b&gt;Контрастность (типичная)&lt;/b&gt;&lt;/p&gt;\r\n&lt;ul&gt;\r\n	&lt;li&gt;\r\n		700:1&lt;/li&gt;\r\n&lt;/ul&gt;\r\n&lt;p&gt;\r\n	&lt;b&gt;Время отклика (типичное)&lt;/b&gt;&lt;/p&gt;\r\n&lt;ul&gt;\r\n	&lt;li&gt;\r\n		16 ms&lt;/li&gt;\r\n&lt;/ul&gt;\r\n&lt;p&gt;\r\n	&lt;b&gt;Шаг пикселя&lt;/b&gt;&lt;/p&gt;\r\n&lt;ul&gt;\r\n	&lt;li&gt;\r\n		Cinema HD 30 дюймов: 0,250 мм&lt;/li&gt;\r\n&lt;/ul&gt;\r\n&lt;p&gt;\r\n	&lt;b&gt;Покрытие экрана&lt;/b&gt;&lt;/p&gt;\r\n&lt;ul&gt;\r\n	&lt;li&gt;\r\n		Матовое твердое покрытие&lt;/li&gt;\r\n&lt;/ul&gt;\r\n&lt;p&gt;\r\n	&lt;b&gt;Органы управления (аппаратные и программные)&lt;/b&gt;&lt;/p&gt;\r\n&lt;ul&gt;\r\n	&lt;li&gt;\r\n		Питание дисплея,&lt;/li&gt;\r\n	&lt;li&gt;\r\n		Сон и пробуждение системы&lt;/li&gt;\r\n	&lt;li&gt;\r\n		Яркость&lt;/li&gt;\r\n	&lt;li&gt;\r\n		Наклон монитора&lt;/li&gt;\r\n&lt;/ul&gt;\r\n&lt;p&gt;\r\n	&lt;b&gt;Разъемы и кабели&lt;/b&gt;&lt;br&gt;\r\n	Кабель&lt;/p&gt;\r\n&lt;ul&gt;\r\n	&lt;li&gt;\r\n		DVI (Digital Visual Interface)&lt;/li&gt;\r\n	&lt;li&gt;\r\n		FireWire 400&lt;/li&gt;\r\n	&lt;li&gt;\r\n		USB 2.0&lt;/li&gt;\r\n	&lt;li&gt;\r\n		DC power (24 V)&lt;/li&gt;\r\n&lt;/ul&gt;\r\n&lt;p&gt;\r\n	Разъемы&lt;/p&gt;\r\n&lt;ul&gt;\r\n	&lt;li&gt;\r\n		Двухпортовый концентратор USB 2.0 с собственным питанием&lt;/li&gt;\r\n	&lt;li&gt;\r\n		Два порта FireWire 400&lt;/li&gt;\r\n	&lt;li&gt;\r\n		Замок Kensington&lt;/li&gt;\r\n&lt;/ul&gt;\r\n&lt;p&gt;\r\n	&lt;b&gt;Адаптер крепления VESA&lt;/b&gt;&lt;br&gt;\r\n	Нужен дополнительный адаптер Cinema Display VESA Mount Adapter (M9649G/A)&lt;/p&gt;\r\n&lt;ul&gt;\r\n	&lt;li&gt;\r\n		Совместим с креплениями VESA FDMI (MIS-D, 100, C)&lt;/li&gt;\r\n&lt;/ul&gt;\r\n&lt;p&gt;\r\n	&lt;b&gt;Электрические требования&lt;/b&gt;&lt;/p&gt;\r\n&lt;ul&gt;\r\n	&lt;li&gt;\r\n		Входное напряжение: 100–240 В переменного тока, 50–60 Гц&lt;/li&gt;\r\n	&lt;li&gt;\r\n		Максимальная мощность в работе: 150 Вт&lt;/li&gt;\r\n	&lt;li&gt;\r\n		Режим энергосбережения: 3 Вт или меньше&lt;/li&gt;\r\n&lt;/ul&gt;\r\n&lt;p&gt;\r\n	&lt;b&gt;Условия среды&lt;/b&gt;&lt;/p&gt;\r\n&lt;ul&gt;\r\n	&lt;li&gt;\r\n		Рабочая температура: от 10° до 35° C (от 50° до 95° F)&lt;/li&gt;\r\n	&lt;li&gt;\r\n		Температура хранения: от -40° до 47° C (от -40° до 116° F)&lt;/li&gt;\r\n	&lt;li&gt;\r\n		Влажность при работе: от 20% до 80% без конденсата&lt;/li&gt;\r\n	&lt;li&gt;\r\n		Максимальная высота работы: 10 000 футов&lt;/li&gt;\r\n&lt;/ul&gt;\r\n&lt;p&gt;\r\n	&lt;b&gt;Сертификаты&lt;/b&gt;&lt;/p&gt;\r\n&lt;ul&gt;\r\n	&lt;li&gt;\r\n		FCC Part 15 Class B&lt;/li&gt;\r\n	&lt;li&gt;\r\n		EN55022 Class B&lt;/li&gt;\r\n	&lt;li&gt;\r\n		EN55024&lt;/li&gt;\r\n	&lt;li&gt;\r\n		VCCI Class B&lt;/li&gt;\r\n	&lt;li&gt;\r\n		AS/NZS 3548 Class B&lt;/li&gt;\r\n	&lt;li&gt;\r\n		CNS 13438 Class B&lt;/li&gt;\r\n	&lt;li&gt;\r\n		ICES-003 Class B&lt;/li&gt;\r\n	&lt;li&gt;\r\n		ISO 13406 part 2&lt;/li&gt;\r\n	&lt;li&gt;\r\n		MPR II&lt;/li&gt;\r\n	&lt;li&gt;\r\n		IEC 60950&lt;/li&gt;\r\n	&lt;li&gt;\r\n		UL 60950&lt;/li&gt;\r\n	&lt;li&gt;\r\n		CSA 60950&lt;/li&gt;\r\n	&lt;li&gt;\r\n		EN60950&lt;/li&gt;\r\n	&lt;li&gt;\r\n		ENERGY STAR&lt;/li&gt;\r\n	&lt;li&gt;\r\n		TCO ''03&lt;/li&gt;\r\n&lt;/ul&gt;\r\n&lt;p&gt;\r\n	&lt;b&gt;Размеры и вес&lt;/b&gt;&lt;br&gt;\r\n	Дисплей Apple Cinema HD 30 дюймов&lt;/p&gt;\r\n&lt;ul&gt;\r\n	&lt;li&gt;\r\n		Высота: 21,3 дюйма (54,3 см)&lt;/li&gt;\r\n	&lt;li&gt;\r\n		Ширина: 27,2 дюйма (68,8 см)&lt;/li&gt;\r\n	&lt;li&gt;\r\n		Глубина: 8,46 дюйма (21,5 см)&lt;/li&gt;\r\n	&lt;li&gt;\r\n		Вес: 27,5 фунта (12,5 кг)&lt;/li&gt;\r\n&lt;/ul&gt;\r\n&lt;p&gt;\r\n	&lt;b&gt;Требования к системе&lt;/b&gt;&lt;/p&gt;\r\n&lt;ul&gt;\r\n	&lt;li&gt;\r\n		Mac Pro, любые варианты графики&lt;/li&gt;\r\n	&lt;li&gt;\r\n		MacBook Pro&lt;/li&gt;\r\n	&lt;li&gt;\r\n		Power Mac G5 (PCI-X) с ATI Radeon 9650 или новее либо NVIDIA GeForce 6800 GT DDL или новее&lt;/li&gt;\r\n	&lt;li&gt;\r\n		Power Mac G5 (PCI Express), любые варианты графики&lt;/li&gt;\r\n	&lt;li&gt;\r\n		PowerBook G4 с поддержкой dual-link DVI&lt;/li&gt;\r\n	&lt;li&gt;\r\n		ПК с Windows и видеокарта с портами DVI, цифровой полосой dual-link и стандартом VESA DDC для автоматического подключения&lt;/li&gt;\r\n&lt;/ul&gt;\r\n',
        '', 'Apple Cinema 30', '', ''),
       (30, 2, 'Canon EOS 5D',
        '&lt;p&gt;\r\n	В пресс-материалах Canon об EOS 5D сказано, что камера «определяет новую категорию цифровых зеркальных аппаратов», и хотя к маркетинговым формулировкам обычно стоит относиться спокойно, здесь это довольно точно. EOS 5D не похож на прежние цифровые зеркальные камеры: полнокадровый сенсор (размер кадра 35 мм) высокого разрешения на 12,8 мегапикселя совмещен с относительно компактным корпусом, чуть крупнее EOS 20D, хотя в руке он заметно массивнее. EOS 5D стоит между EOS 20D и профессиональными EOS-1D. Важное отличие от последних: у EOS 5D нет пылевлагозащиты. Canon прямо не называет EOS 5D профессиональной камерой, но она очевидна тем, кому нужна качественная зеркалка легче EOS-1D. Она также заинтересует владельцев EOS 20D (главное, чтобы у них не было слишком много объективов EF-S...) äë&lt;/p&gt;\r\n',
        '', 'Canon EOS 5D', '', '');

